def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator * 2 + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)
        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(raw * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=True)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            rows = [row for row in packages[name]
                    if row["version"] not in blocked.get(name, []) and
                    (name not in pins or row["version"] == pins[name])]
            choices.append([None] + rows)

        best_vector = None
        best_versions = None
        for selection in product(*choices):
            installed = {name: row for name, row in zip(names, selection)
                         if row is not None}
            okay = True
            for name, (low, high) in roots.items():
                row = installed.get(name)
                if row is None or not low <= row["version"] <= high:
                    okay = False
                    break
            if not okay:
                continue

            edges = {name: [] for name in installed}
            for name, row in installed.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    other = installed.get(target)
                    if other is None or not dep["min"] <= other["version"] <= dep["max"]:
                        okay = False
                        break
                    edges[name].append(target)
                if not okay:
                    break
            if not okay:
                continue

            # Installed packages must be precisely the active closure of roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                if name not in installed:
                    okay = False
                    break
                reachable.add(name)
                stack.extend(edges[name])
            if not okay or reachable != set(installed):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True
            if any(not visit(name) for name in installed):
                continue

            vector = tuple(installed[name]["version"] if name in installed else -1
                           for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = {name: row["version"]
                                 for name, row in installed.items()}
        if best_vector is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        node_bits = {}
        for index, node in enumerate(required):
            node_bits[node] = node_bits.get(node, 0) | (1 << index)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        start = data["start"]
        initial_mask = node_bits.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        distances = {initial: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], remaining)]
                if remaining:
                    durations.append((max(1, edge["duration"] -
                                           edge.get("discount", 0)), remaining - 1))
                for duration, left in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask | node_bits.get(next_node, 0)
                    next_state = (next_node, next_mask, left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_mask, left))
        return {"arrival": None}
    return solve


